suppressPackageStartupMessages({library(dplyr);library(readr);library(ggplot2);library(ggthemes)})
args<-commandArgs(trailingOnly=TRUE);stopifnot(length(args)==1L);a<-read_csv(args[1],show_col_types=FALSE)
g <- ggplot(a,aes(year,distance_nm,color=season,linetype=window))+geom_line()+geom_point(data=filter(a,window=='Available season'),size=1.7)+scale_color_manual(values=c('A'='#D55E00','B'='#0072B2'),labels=c('A season','B season'),name=NULL)+scale_linetype_manual(values=c('Available season'='solid','Through September 18'='dashed'),name=NULL)+theme_few()+theme(legend.position='bottom')+labs(x='Year',y='Mean pairwise tow distance (nautical miles)',title='Fleet dispersion in the A and B seasons',subtitle='Daily tow pairs within CP and observed CV groups; 2000–2026',caption='Pairs are pooled within year and season, within vessel groups.\nDashed lines restrict every year to September 18. 2026 B season and catcher-vessel coverage are incomplete.')
ggsave('2026/assets/figure-007.png',g,width=10,height=6,dpi=180)
